ddls.VEHICLEGROUPS:
CREATE TABLE VEHICLEGROUPS (
    ID_VEHICLEGROUPS INT,
    Description NVARCHAR(100)
);

ddls.TERMINALS:
CREATE TABLE TERMINALS (
    ID_TERMINALS INT,
    Description NVARCHAR(100),
    city NVARCHAR(100),
    StationCode NVARCHAR(50)
);

ddls.CARDS:
CREATE TABLE CARDS (
    ID_CARDS INT,
    PAN NVARCHAR(40),
    CardLayoutsID INT,
    VehiclesID INT
);

ddls.COSTCENTERS:
CREATE TABLE COSTCENTERS (
    ID_COSTCENTERS INT,
    Description NVARCHAR(150)
);

ddls.CUSTOMERS:
CREATE TABLE CUSTOMERS (
    ID_CUSTOMERS INT,
    CustomerNumber NVARCHAR(50),
    CustomerName NVARCHAR(100)
);

ddls.FUELRATIO:
CREATE TABLE FUELRATIO (
    date DATE,
    coal_bism FLOAT,
    ob_bism FLOAT,
    port_bism FLOAT
);

ddls.TERMINAL_CONFIGURATIONS:
CREATE TABLE TERMINAL_CONFIGURATIONS (
    id INT,
    operation_type NVARCHAR(50),
    terminal_ids NVARCHAR(MAX)
);

ddls.USER_ACCESS:
CREATE TABLE USER_ACCESS (
    id INT,
    user_id INT,
    terminal_ids NVARCHAR(MAX)
);
